import {
  FaLinkedinIn,
  FaFacebookF,
  FaInstagram,
  FaTwitter,
} from "react-icons/fa6";
import { TypeAnimation } from "react-type-animation";

export default function Footer() {
  return (
    <footer className="bg-blue-700 text-white py-10 px-6 md:px-20">
      <div className="max-w-7xl mx-auto grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-10">
        <div>
          <h3 className="text-lg font-semibold mb-4">
            <TypeAnimation
              style={{
                whiteSpace: "pre-line",
                display: "block",
              }}
              sequence={[
                "Software",
                1200,
                `Software Recruitment`,
                1200,
                `Software Recruitment Co.`,
                1200,
                ``,
                1200,
                "",
              ]}
              repeat={Infinity}
            />
          </h3>
          <div className="flex space-x-4 text-xl">
            <FaLinkedinIn className="hover:animate-pulse transition duration-300 cursor-pointer" />
            <FaFacebookF className="hover:animate-pulse transition duration-300 cursor-pointer" />
            <FaInstagram className="hover:animate-pulse transition duration-300 cursor-pointer" />
            <FaTwitter className="hover:animate-pulse transition duration-300 cursor-pointer" />
          </div>
        </div>

        <div>
          <h4 className="text-lg font-semibold mb-3">Explore</h4>
          <ul className="space-y-2 text-sm">
            {[
              "Homepage",
              "For jobseekers",
              "For clients",
              "Our sectors",
              "Resources",
              "Contact us",
            ].map((item, i) => (
              <li
                key={i}
                className="transition-all duration-300 transform hover:scale-105 hover:font-semibold cursor-pointer"
              >
                {item}
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h4 className="text-lg font-semibold mb-3">Sectors</h4>
          <ul className="space-y-2 text-sm">
            {[
              "Software engineering",
              "DevOps",
              "Cloud",
              "Infrastructure",
              "Testing",
              "Security",
            ].map((item, i) => (
              <li
                key={i}
                className="transition-all duration-300 transform hover:scale-105 hover:font-semibold cursor-pointer"
              >
                {item}
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h4 className="text-lg font-semibold mb-3">Services</h4>
          <ul className="space-y-2 text-sm">
            {["Nav item", "Nav item", "Nav item", "Nav item", "Nav item"].map(
              (item, i) => (
                <li
                  key={i}
                  className="transition-all duration-300 transform hover:scale-105 hover:font-semibold cursor-pointer"
                >
                  {item}
                </li>
              )
            )}
          </ul>
        </div>
      </div>
    </footer>
  );
}
